INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'AI-METER-STREAM-1a: qnfo-ai-search ask streams a Workers AI reply and books no output tokens (the metering wrapper reads res.usage, a stream has none)',
 'code-task: repo=qnfo-workers path=qnfo-ai-search/worker.js' || char(10) ||
 'code-anchor: async function ask(request, env, ctx) {' || char(10) ||
 'code-probe: {"paths": ["qnfo-ai-search/worker.js"], "contains": "AI-METER-STREAM-1"}' || char(10) || char(10) ||
 'Charter pillar cost (program QNFO.INFRA), roadmap RM-COST-FREE-FIRST-PARITY-1 (row 17, the per-path streaming policy check). Found by scanning every worker.js for a Workers AI call whose arguments pass stream: true (2026-11-05): exactly two sites, this one and qnfo-ops handleWaiRelay (AI-METER-STREAM-1b).' || char(10) ||
 'Evidence: ask() calls env.AI.run(m, { messages, stream: true, ... }) inside runWriter. env is wrapped by __aiAttrEnv, whose counter row reads res.usage; a streamed reply is a ReadableStream with no usage, so the row books in_tok = prompt chars / 4 and out_tok = 0, and the neurons are the input share only. ai_call_counters qnfo-ai-search 2026-11-04: 35 calls, 12,307 neurons (deepseek-v4-flash-0731 27 calls 11,239, kimi-k2.6 2 calls 842); the output share is missing from every streamed ask.' || char(10) ||
 'DO: after the stream has been read to its end (the caller holds the tokens back, ASK-GROUND-2), add the output estimate to the counter: out_tok = streamed text chars / 4 and the neurons for it at the model rate (the __AI_ATTR_RATES table in the same file), in one UPDATE of the same ai_call_counters row or one extra row with purpose binding-stream; mark the change with the id AI-METER-STREAM-1 in a comment (the code-probe reads it). Test: a fake stream of known length books the expected out_tok and neurons. Bump with python scripts/worker_release.py bump qnfo-ai-search.' || char(10) ||
 'Definition of done: merged, deployed, and ai_call_counters qnfo-ai-search out_tok is above 0 for a day with asks; recorded in issue_triage.close_evidence. Prediction: qnfo-ai-search attributed neurons +20 to +60 percent for deepseek-v4-flash-0731 (v_ai_meter_vs_counters); no spend change.',
 'session:w2f-a', 'optimization', 'low', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'AI-METER-STREAM-1a%' AND status = 'open');

